public sealed class DbFixture : IDisposable
{
    public string Connection { get; } = "memory";
    public void Dispose() { }
}

/// <summary>
/// Shared fixture instance used by test classes that were in the xUnit "Db" collection.
/// </summary>
internal static class SharedDbFixture
{
    private static readonly Lazy<DbFixture> s_instance = new(() => new DbFixture());
    public static DbFixture Instance => s_instance.Value;

    [AssemblyCleanup]
    public static void Cleanup() =>
        (s_instance.IsValueCreated ? s_instance.Value : null)?.Dispose();
}

